Section CLASS.
  Variables mem0 Mfr : word -> option byte.
  Variable rom : word -> option byte.
  Variables t fs sparg bot g35 : Z.
  Variables flag rs : Z -> Z -> Z.
  Hypothesis Ht : (0x1000000 <= t - 160)%Z /\ (t < 2 ^ 64)%Z.
  Hypothesis Hfs : (0x6b3000 <= fs)%Z /\ (fs + 4096 + 32768 + 11 * 2 ^ 20 < 2 ^ 47)%Z /\ (fs + 4096 + 32768 + 11 * 2 ^ 20 <= t - 160 \/ t <= fs)%Z.
  Hypothesis Happ : (fs + 4096 + 32768 + 11 * 2 ^ 20 <= 0x7fff7000 \/ 0x10007fff8000 <= fs)%Z.
  Hypothesis Hshz : (gc_shz_hi fs <= t - 160 \/ t <= gc_shz_lo fs)%Z.
  Hypothesis Hsp : (0 <= sparg < 2 ^ 64)%Z /\ (0 <= bot < 2 ^ 64)%Z.
  Hypothesis Hok : store_ok ASEGS mem0 (Z_to_bv 64 (t - 160)) 160%nat = true.
  Hypothesis Hwfs : store_ok ASEGS mem0 (Z_to_bv 64 fs) (Z.to_nat (4096 + 32768 + 11 * 2 ^ 20)) = true.
  Hypothesis HF0 : forall c i, gc_valid c i ->
    rdn ASEGS mem0 (Z_to_bv 64 (gc_fl fs c i)) 1%nat = Some [Z_to_bv 8 (flag c i)] /\ (0 <= flag c i < 256)%Z.
  Hypothesis HCL : forall M', (forall x : word, gc_outz (t - 160) t fs (bv_unsigned x) -> M' x = mem0 x) ->
    rdn ASEGS M' (Z_to_bv 64 (fs + 88)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 20))
    /\ rt_layout_globs M'
    /\ (forall c i, gc_valid c i -> flag c i <> 0%Z ->
          rdn ASEGS M' (Z_to_bv 64 (gc_fr fs c i + 24)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 (rs c i))) /\ (0 <= rs c i < 2 ^ 64)%Z).
  Hypothesis HFR : rdn ASEGS Mfr (Z_to_bv 64 (t - 120)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x15d6a8))
                /\ rdn ASEGS Mfr (Z_to_bv 64 (t - 128)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x15d6b0))
                /\ rdn ASEGS Mfr (Z_to_bv 64 (t - 136)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x15d6a0)).
  Hypothesis Hcol6 : forall c i, gc_valid c i -> gc_col sparg bot flag rs c i -> (c <= 6)%Z.
  Hypothesis Hshok : forall c i, gc_valid c i -> gc_col sparg bot flag rs c i ->
    store_ok ASEGS mem0 (Z_to_bv 64 (gc_sh fs c i)) (Z.to_nat (2 ^ (3 + c))) = true.

  #[local] Abbreviation col := (gc_col sparg bot flag rs).
  #[local] Abbreviation GCM := (gcm mem0 (t - 160) t fs col).
  #[local] Abbreviation FRM := (frm Mfr t).

  Definition gcl2_inv (rg : bvmap 5 word) (c : Z) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S22;Y2;1;A1;o20;#0;Y6;00;A1;o20;#2;A1;i19;#3;A1;o3;Y4;4;A1;o3;Y4;9;Y2;3;A1;o3;#7;Y3;0;A1;o3;#9;Y4;2;A1;o3;#11;Y3;1;A1;o3;#13;Y1;0;A1;o3;#15;A1;o3;Y4;a;A1;o3;Y4;6;A1;o3;Y4;7;A1;o3;Y4;c;Y2;2;Lrg;RA2;k179;#1;#4;Lc;Ri0;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#5;cvo70;A2;k182;#1;#5;A2;k27;#3;r1;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#6;cvo70;A2;k182;#1;#6;A2;k27;#3;vfs;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#8;cvo70;A2;k182;#1;#8;A2;k27;#3;A1;o3;o48;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#10;cvo70;A2;k182;#1;#10;A2;k27;#3;A2;k1;vfs;A1;o3;Y12;000;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#12;cvo70;A2;k182;#1;#12;A2;k27;#3;vbot;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#14;cvo70;A2;k182;#1;#14;A2;k27;#3;vsparg;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#16;cvo70;A2;k182;#1;#16;A2;k27;#3;A2;k2;vt;A1;o3;Y7;10;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#17;cvo70;A2;k182;#1;#17;A2;k27;#3;o11;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#18;cvo70;A2;k182;#1;#18;A2;k27;#3;A1;o3;Y20;5c9b8;A2;i9;A3;i15;#4;A2;k180;r2;A3;o181;#1;#19;cvo70;A2;k182;#1;#19;A2;k27;#3;vg35;A3;i15;#4;A2;k180;r2;A3;o181;#1;#20;cvo70;A2;k182;#1;#20;A2;k27;#3;A1;o3;#21;").
  Definition gcl_keeps2 (regs regs' : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S23;Y2;1;A1;o20;#0;A1;i19;A1;o20;Y6;00;A2;k179;#1;#2;A1;i19;#1;A1;o3;#0;Y3;2;A1;o3;#6;A1;o3;Y3;3;Y3;4;A1;o3;#9;Y3;5;A1;o3;#11;A1;o3;Y3;6;A1;o3;Y3;7;Y4;0;A1;o3;#15;A1;o3;Y4;1;A1;o3;Y4;b;A1;o3;Y4;5;A1;o3;Y4;8;A1;o3;Y4;3;A1;o3;Y4;4;Lregs;R#3;Lregs';R#3;Pr;R#4;P~RA1;k14;A3;i15;#4;r1;A3;o181;#1;#5;cvo70;A2;k182;#1;#5;P~RA1;k14;A3;i15;#4;r2;A3;o181;#1;#7;cvo70;A2;k182;#1;#7;P~RA1;k14;A3;i15;#4;r3;A3;o181;#1;#8;cvo70;A2;k182;#1;#8;P~RA1;k14;A3;i15;#4;r4;A3;o181;#1;#10;cvo70;A2;k182;#1;#10;P~RA1;k14;A3;i15;#4;r5;A3;o181;#1;#12;cvo70;A2;k182;#1;#12;P~RA1;k14;A3;i15;#4;r6;A3;o181;#1;#13;cvo70;A2;k182;#1;#13;P~RA1;k14;A3;i15;#4;r7;A3;o181;#1;#14;cvo70;A2;k182;#1;#14;P~RA1;k14;A3;i15;#4;r8;A3;o181;#1;#16;cvo70;A2;k182;#1;#16;P~RA1;k14;A3;i15;#4;r9;A3;o181;#1;#17;cvo70;A2;k182;#1;#17;P~RA1;k14;A3;i15;#4;r10;A3;o181;#1;#18;cvo70;A2;k182;#1;#18;P~RA1;k14;A3;i15;#4;r11;A3;o181;#1;#19;cvo70;A2;k182;#1;#19;P~RA1;k14;A3;i15;#4;r12;A3;o181;#1;#20;cvo70;A2;k182;#1;#20;P~RA1;k14;A3;i15;#4;r13;A3;o181;#1;#21;cvo70;A2;k182;#1;#21;P~RA1;k14;A3;i15;#4;r14;A3;o181;#1;#22;cvo70;A2;k182;#1;#22;A3;i15;#2;A2;k180;r16;r15;A2;k180;r17;r15;").

  #[local] Ltac kp14 := intros r; intros; repeat (rewrite getr_other; [| intros ->; match goal with Hn : ?a <> ?a |- _ => exact (Hn eq_refl) end]); reflexivity.

  Lemma gcc_class_run : forall regs M c,
    gcl2_inv regs c -> (0 <= c <= 10)%Z -> GCM (gc_done_lt c 0) M -> FRM M ->
    exists regs' M',
